/**
 * Block Puzzle — zero-dep client bundler (ESM pipeline).
 *
 * Outputs:
 *   public/dist/client.bundle.js   — <script src> (IIFE, shared scope)
 *   public/dist/client.bundle.mjs  — type="module" / import
 *   public/dist/client.bundle.js.map — basic source map (module ranges)
 *   public/dist/manifest.json
 *
 *   node scripts/bundle-client.js
 *   node scripts/bundle-client.js --watch
 *   node scripts/bundle-client.js --no-minify
 */
'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ROOT = path.join(__dirname, '..');
const OUT_DIR = path.join(ROOT, 'public', 'dist');
const MINIFY = !process.argv.includes('--no-minify');

const MODULES = [
  'public/shared/rules.js',
  'public/match-client.js',
  'public/js/00-state.js',
  'public/js/00-perf.js',
  'public/js/00-i18n.js',
  'public/js/01-cosmetics.js',
  'public/js/02-bots-achievements-settings.js',
  'public/js/03-audio.js',
  'public/js/04-profile-friends.js',
  'public/js/05-soft-render.js',
  'public/js/06-match-liveness.js',
  'public/js/07-match-flow-ui.js',
  'public/js/08-screens-gameplay.js',
  'public/js/09-offline-and-ranked.js',
  'public/js/10-match-handlers.js',
  'public/js/11-private-rooms-ui.js',
  'public/js/12-boot.js',
  'public/js/13-performance.js',
  'public/js/14-settings-ui.js'
];

/** Reserved for future true code-split (modules must not rely on shared IIFE scope). */
const DEFERRED_MODULES = [];

function readVersion() {
  try {
    return JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8')).version || '0.0.0';
  } catch (_) {
    return '0.0.0';
  }
}

/**
 * After rules UMD runs, mirror common free globals used by legacy game modules.
 */
const RULES_MIRROR = `
/* mirror BPRules → free globals expected by legacy modules */
(function (g) {
  try {
    var R = g.BPRules;
    if (!R) return;
    var keys = [
      'SIZE','DEFAULT_COLORS','SHAPES','emptyGrid','cloneGrid','normalizeShape',
      'randomPiece','dealThree','canPlaceOn','clearLinesOnGrid','clearLinesSilent',
      'bonusFor','chainBonusFor','placePoints','serializePieces','findAllPlacements',
      'sideHasPlayable','MIN_PLACE_INTERVAL_MS','PLACE_BURST_WINDOW_MS','PLACE_BURST_MAX',
      'DC_LIMIT_MS','AFK_WARN_MS','AFK_LIMIT_MS','DETACH_GRACE_MS','MATCH_START_GRACE_MS',
      'AFK_WARN_BROADCAST_MS','PROTOCOL_VERSION'
    ];
    for (var i = 0; i < keys.length; i++) {
      var k = keys[i];
      if (typeof g[k] === 'undefined' && R[k] !== undefined) g[k] = R[k];
    }
  } catch (e) {}
})(typeof globalThis !== 'undefined' ? globalThis : (typeof window !== 'undefined' ? window : this));
`;

function normalizeModule(rel, src) {
  src = src.replace(/^\uFEFF/, '').replace(/\r\n/g, '\n');
  let out = '/* ===== ' + rel + ' ===== */\n' + src;
  if (!out.endsWith('\n')) out += '\n';
  if (rel.endsWith('shared/rules.js') || rel.endsWith('public/shared/rules.js') || /\/shared\/rules\.js$/.test(rel)) {
    out += RULES_MIRROR;
  }
  return out;
}

/**
 * Conservative zero-dep minify:
 * - strip block comments
 * - collapse runs of blank lines
 * - trim trailing whitespace per line
 * Does not touch line comments (URLs / regex risk) or string contents via a full parser.
 */
function lightMinify(src) {
  // Remove block comments. Avoid matching inside strings as best-effort:
  // skip /* that appear after an odd number of unescaped quotes on the same line prefix — simplified: global strip is OK for this codebase.
  let out = src.replace(/\/\*[\s\S]*?\*\//g, '');
  out = out.replace(/[ \t]+$/gm, '');
  out = out.replace(/\n{3,}/g, '\n\n');
  out = out.replace(/^\n+/, '');
  return out;
}

function build() {
  const VERSION = readVersion();
  fs.mkdirSync(OUT_DIR, { recursive: true });

  const parts = [];
  const included = [];
  const moduleRanges = []; // for source map / manifest
  let lineCursor = 0; // 0-based line index inside IIFE body (approx)

  // Banner is outside the IIFE; track lines for map relative to full classic file later
  for (const rel of MODULES) {
    const abs = path.join(ROOT, rel);
    if (!fs.existsSync(abs)) {
      console.warn('[bundle] missing', rel);
      continue;
    }
    const chunk = normalizeModule(rel, fs.readFileSync(abs, 'utf8'));
    const startLine = lineCursor;
    const lineCount = chunk.split('\n').length;
    lineCursor += lineCount;
    moduleRanges.push({
      file: rel,
      startLine,
      endLine: lineCursor - 1,
      bytes: Buffer.byteLength(chunk)
    });
    parts.push(chunk);
    included.push(rel);
  }

  const bodyRaw = parts.join('\n');
  const body = MINIFY ? lightMinify(bodyRaw) : bodyRaw;
  const hash = crypto.createHash('sha256').update(body).digest('hex').slice(0, 12);
  const banner =
    '/**\n * Block Puzzle client bundle v' + VERSION + '\n' +
    ' * Generated by scripts/bundle-client.js — DO NOT EDIT\n' +
    ' * modules: ' + included.length + ' | sha256:' + hash +
    (MINIFY ? ' | minified' : '') + '\n */\n';

  const classic =
    banner +
    '(function (global) {\n"use strict";\n' +
    body +
    '\n})(typeof globalThis !== "undefined" ? globalThis : (typeof window !== "undefined" ? window : this));\n' +
    '//# sourceMappingURL=client.bundle.js.map\n';

  const esm =
    banner +
    '// ESM build — side effects attach to globalThis; named exports for tooling\n' +
    body +
    '\nexport const BP_VERSION = "' + VERSION + '";\n' +
    'export const BP_BUNDLE_HASH = "' + hash + '";\n' +
    'export default { version: BP_VERSION, hash: BP_BUNDLE_HASH };\n';

  fs.writeFileSync(path.join(OUT_DIR, 'client.bundle.js'), classic);
  fs.writeFileSync(path.join(OUT_DIR, 'client.bundle.mjs'), esm);

  // Lightweight source map: lists original modules + ranges in the pre-minify body.
  // Enough to locate which module a stack frame roughly came from.
  const sourceMap = {
    version: 3,
    file: 'client.bundle.js',
    sourceRoot: '',
    sources: included.map((m) => '../' + m.replace(/^public\//, '')),
    sourcesContent: included.map((rel) => {
      try {
        return fs.readFileSync(path.join(ROOT, rel), 'utf8');
      } catch (_) {
        return null;
      }
    }),
    names: [],
    // Empty mappings — browsers still expose sourcesContent for manual inspection.
    // Full VLQ identity mappings would require a line-by-line encoder; keep zero-dep.
    mappings: '',
    x_modules: moduleRanges,
    x_minified: MINIFY,
    x_version: VERSION,
    x_hash: hash
  };
  fs.writeFileSync(
    path.join(OUT_DIR, 'client.bundle.js.map'),
    JSON.stringify(sourceMap)
  );

  const manifest = {
    version: VERSION,
    hash,
    minified: MINIFY,
    generatedAt: new Date().toISOString(),
    modules: included,
    moduleRanges,
    bytes: {
      classic: Buffer.byteLength(classic),
      esm: Buffer.byteLength(esm),
      classicRaw: Buffer.byteLength(bodyRaw)
    }
  };
  // Deferred chunk (private rooms UI) — smaller main bundle, load after paint
  let deferredBytes = 0;
  if (typeof DEFERRED_MODULES !== 'undefined' && DEFERRED_MODULES.length) {
    const dParts = [];
    const dIncluded = [];
    for (const rel of DEFERRED_MODULES) {
      const abs = path.join(ROOT, rel);
      if (!fs.existsSync(abs)) {
        console.warn('[bundle] missing deferred', rel);
        continue;
      }
      dParts.push(normalizeModule(rel, fs.readFileSync(abs, 'utf8')));
      dIncluded.push(rel);
    }
    if (dParts.length) {
      const dBodyRaw = dParts.join('\n');
      const dBody = MINIFY ? lightMinify(dBodyRaw) : dBodyRaw;
      const dHash = crypto.createHash('sha256').update(dBody).digest('hex').slice(0, 12);
      const dBanner =
        '/**\n * Block Puzzle deferred client chunk v' + VERSION + '\n' +
        ' * private-rooms UI — DO NOT EDIT\n' +
        ' * modules: ' + dIncluded.length + ' | sha256:' + dHash +
        (MINIFY ? ' | minified' : '') + '\n */\n';
      const dClassic =
        dBanner +
        '(function (global) {\n"use strict";\n' +
        dBody +
        '\n})(typeof globalThis !== "undefined" ? globalThis : (typeof window !== "undefined" ? window : this));\n';
      fs.writeFileSync(path.join(OUT_DIR, 'client.deferred.js'), dClassic);
      deferredBytes = Buffer.byteLength(dClassic);
      manifest.deferred = {
        file: 'client.deferred.js',
        modules: dIncluded,
        bytes: deferredBytes,
        hash: dHash
      };
    }
  }

  fs.writeFileSync(path.join(OUT_DIR, 'manifest.json'), JSON.stringify(manifest, null, 2));
  console.log(
    '[bundle] OK v' + VERSION + ' hash=' + hash +
    ' modules=' + included.length +
    (MINIFY ? ' minified' : '') +
    ' classic=' + manifest.bytes.classic + 'B' +
    ' esm=' + manifest.bytes.esm + 'B' +
    (deferredBytes ? ' deferred=' + deferredBytes + 'B' : '') +
    (MINIFY && manifest.bytes.classicRaw
      ? ' (raw body ' + manifest.bytes.classicRaw + 'B)'
      : '')
  );
  return manifest;
}

function watch() {
  console.log('[bundle] watch mode');
  build();
  let t = null;
  for (const rel of MODULES) {
    try {
      fs.watch(path.join(ROOT, rel), () => {
        if (t) clearTimeout(t);
        t = setTimeout(() => {
          try { build(); } catch (e) { console.error(e); }
        }, 150);
      });
    } catch (_) {}
  }
}

if (require.main === module) {
  if (process.argv.includes('--watch') || process.argv.includes('-w')) watch();
  else build();
}

module.exports = { build, MODULES, OUT_DIR, lightMinify };
